mapper.select:
SELECT rule_id, promotion_code, promotion_name, promotion_type, status, start_time, end_time, min_deposit, bonus_rate, max_bonus, wagering_multiplier, max_claims_per_player, bonus_expiry_days, game_restriction, create_time, update_time FROM t_promotion_rule WHERE deleted = FALSE
AND (promotion_name LIKE CONCAT('%', #{query.keyword}, '%') OR promotion_code LIKE CONCAT('%', #{query.keyword}, '%'))
AND promotion_type = #{query.promotionType}
AND status = #{query.status}
ORDER BY create_time DESC

SELECT *
FROM t_promotion_rule
WHERE tenant_id = #{tenantId}
      AND promotion_code = #{promotionCode}
      AND deleted = FALSE
